// Gray-code exact edge expansion. Vertex n-1 fixed outside; complements accounted for in denominator. Integer comparisons only. Input adjacency masks.
use std::io::{self,BufRead};fn main(){for l in io::stdin().lock().lines(){let a:Vec<u64>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let n=a.len()as i32;assert!(n<=35);let d:Vec<i32>=a.iter().map(|x|x.count_ones()as i32).collect();let(mut best,mut den,mut mask)=(n,1,1u64);let(mut s,mut cut,mut size)=(0u64,0i32,0i32);for i in 1u64..1u64<<(n-1){let v=i.trailing_zeros()as usize;let direction=1-2*((s>>v)&1)as i32;cut+=direction*(d[v]-2*(a[v]&s).count_ones()as i32);size+=direction;s^=1<<v;let p=size.min(n-size);if cut*den<best*p{best=cut;den=p;mask=s}}println!("{} {} {}",best,den,mask)}}
